async function probe(url, opts) {
  try {
    const t0 = Date.now();
    const resp = await fetch(url, opts);
    const buf = await resp.arrayBuffer();
    return { ok: resp.ok, status: resp.status, bytes: buf.byteLength, type: resp.headers.get("content-type"), ms: Date.now() - t0 };
  } catch (e) {
    return { error: String(e && e.message ? e.message : e) };
  }
}
const r = await probe("https://www.plantuml.com/plantuml/png", {
  method: "POST",
  headers: { "Content-Type": "text/plain" },
  body: "@startuml\nBob -> Alice: Hello\n@enduml",
});
return r;

